import { View, StyleSheet, Dimensions } from 'react-native';
import Svg, { Line, Path, Circle, G, Text as SvgText } from 'react-native-svg';

const DeepNeonGreen = 'rgba(0, 255, 102, 0.67)'; // 0xAA00FF66 (Target)
